},
{
["message"] = "|cff979797|Hpratcopy|h[16:07:52]|h|r Alexstrasza the Life-Binder says: What is the meaning of this, Sabellian? Where are the eggs?",
["serverTime"] = 1788131271,
["r"] = 1,
["extraData"] = {
13,
1,
2,
["n"] = 3,
},
["timestamp"] = 14834.351,
["g"] = 1,
["b"] = 0.6235294342041016,
},
{
["message"] = "|cff979797|Hpratcopy|h[16:07:57]|h|r Wrathion says: Yes, why don't you explain how your ridiculous plan destroyed the future of an entire flight?",
["serverTime"] = 1788131276,
["r"] = 1,
["extraData"] = {
13,
1,
2,
["n"] = 3,
},
["timestamp"] = 14838.851,
["g"] = 1,
["b"] = 0.6235294342041016,
},
{
["message"] = "|cff979797|Hpratcopy|h[16:08:03]|h|r Sabellian says: I apologize for any misunderstandings, Life-Binder. But any report of our extinction is premature.",
["serverTime"] = 1788131282,
["r"] = 1,
["extraData"] = {
13,
1,
2,
["n"] = 3,
},
["timestamp"] = 14845.668,
["g"] = 1,
["b"] = 0.6235294342041016,
},
{
["message"] = "|cff979797|Hpratcopy|h[16:08:13]|h|r Sabellian says: The eggs were never in danger. The cart, and my presence, were merely to draw the attention of our foes and allow my clutch to move unobserved.",
["serverTime"] = 1788131292,
["r"] = 1,
["extraData"] = {
13,
1,
2,
["n"] = 3,
},
["timestamp"] = 14854.768,
["g"] = 1,
["b"] = 0.6235294342041016,
},
{
["message"] = "|cff979797|Hpratcopy|h[16:08:23]|h|r Sabellian says: I have spent millennia rebuilding my flight. As Neltharion's heir I pledge it, and myself, to you.",
["serverTime"] = 1788131302,
["r"] = 1,
["extraData"] = {
13,
1,
2,
["n"] = 3,
},
["timestamp"] = 14865.151,
["g"] = 1,
["b"] = 0.6235294342041016,
},
{
["message"] = "|cff979797|Hpratcopy|h[16:08:31]|h|r Wrathion says: What are you--",
["serverTime"] = 1788131310,
["r"] = 1,
["extraData"] = {
13,
1,
2,
["n"] = 3,
},
["timestamp"] = 14873.184,
["g"] = 1,
["b"] = 0.6235294342041016,
},
{
["message"] = "|cff979797|Hpratcopy|h[16:08:33]|h|r Alexstrasza the Life-Binder says: These eggs are most welcome here, Sabellian. But your part in your father's twisted legacy has earned you no such privilege.",
["serverTime"] = 1788131312,
["r"] = 1,
["extraData"] = {
13,
1,
2,
["n"] = 3,
},
["timestamp"] = 14874.718,
["g"] = 1,
["b"] = 0.6235294342041016,
},
{
["message"] = "|cff979797|Hpratcopy|h[16:08:43]|h|r Alexstrasza the Life-Binder says: I will ensure the eggs are cared for, but I will not be involved in your bickering. That is for the black, not the red, to decide.",
